package negocio;
import java.time.LocalDateTime;
public class EventoComunidad { private long id; private TipoEventoComunidad tipo; private Long convocatoriaId,solicitudId,actorClienteId,actorPerfilId; private String detalleJson; private LocalDateTime fechaEvento;
 public long getId(){return id;} public void setId(long v){id=v;} public TipoEventoComunidad getTipo(){return tipo;} public void setTipo(TipoEventoComunidad v){tipo=v;} public Long getConvocatoriaId(){return convocatoriaId;} public void setConvocatoriaId(Long v){convocatoriaId=v;} public Long getSolicitudId(){return solicitudId;} public void setSolicitudId(Long v){solicitudId=v;} public Long getActorClienteId(){return actorClienteId;} public void setActorClienteId(Long v){actorClienteId=v;} public Long getActorPerfilId(){return actorPerfilId;} public void setActorPerfilId(Long v){actorPerfilId=v;} public String getDetalleJson(){return detalleJson;} public void setDetalleJson(String v){detalleJson=v;} public LocalDateTime getFechaEvento(){return fechaEvento;} public void setFechaEvento(LocalDateTime v){fechaEvento=v;} public void validar(){if(tipo==null)throw new IllegalArgumentException("El tipo de evento es obligatorio.");}}
